float woolDensity(vec3 p) {
    float coarse = fbm(p.xy*2.5 + vec2(p.z*0.6, 0.0));
    float fineH  = noise(p.xy*9.0 + vec2(0.0, p.z*3.0));
    float fineV  = noise(p.yx*9.0 + vec2(p.z*3.0, 0.0));
    return coarse*0.65 + fineH*0.2 + fineV*0.15;
}

